using ComplianceCaseManagement.Cases;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Design;
namespace ComplianceCaseManagement.Infrastructure;

public sealed class CaseDbContext(DbContextOptions<CaseDbContext> options) : DbContext(options) { public DbSet<ComplianceCase> Cases => Set<ComplianceCase>(); public DbSet<CaseAudit> Audit => Set<CaseAudit>(); protected override void OnModelCreating(ModelBuilder b) { var c = b.Entity<ComplianceCase>(); c.HasKey(x => x.Id); c.Property(x => x.Title).HasMaxLength(200); c.Property(x => x.OwnerId).HasMaxLength(100); c.Property(x => x.Status).HasConversion<string>().HasMaxLength(30); c.Property(x => x.Version).IsConcurrencyToken(); c.HasIndex(x => new { x.Status, x.Deadline }); c.HasMany(x => x.Audit).WithOne().HasForeignKey(x => x.CaseId).OnDelete(DeleteBehavior.Restrict); c.Navigation(x => x.Audit).UsePropertyAccessMode(PropertyAccessMode.Field); var a = b.Entity<CaseAudit>(); a.HasKey(x => x.Id); a.Property(x => x.ActorId).HasMaxLength(100); a.Property(x => x.Action).HasMaxLength(500); a.Property(x => x.PreviousStatus).HasConversion<string>().HasMaxLength(30); a.Property(x => x.NewStatus).HasConversion<string>().HasMaxLength(30); a.HasIndex(x => new { x.CaseId, x.OccurredAt }); } public override Task<int> SaveChangesAsync(CancellationToken ct = default) { if (ChangeTracker.Entries<CaseAudit>().Any(x => x.State is EntityState.Modified or EntityState.Deleted)) throw new InvalidOperationException("Audit history is append-only."); return base.SaveChangesAsync(ct); } }
public sealed class CaseDbContextFactory : IDesignTimeDbContextFactory<CaseDbContext> { public CaseDbContext CreateDbContext(string[] a) => new(new DbContextOptionsBuilder<CaseDbContext>().UseSqlServer("Server=localhost;Database=ComplianceCases;Trusted_Connection=True;TrustServerCertificate=True").Options); }
